import{z as o,x as B,o as E,c as i,q as A,j as l,D as n,d as r,s,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"功耗墙与 Dennard 缩放","description":"","frontmatter":{"title":"功耗墙与 Dennard 缩放","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dennard-power-wall.md","filePath":"cs/dennard-power-wall.md","lastUpdated":1791063341000}'),p={name:"cs/dennard-power-wall.md"};function D(C,a,m,F,f,h){const t=B("Mermaid");return E(),i("div",null,[a[2]||(a[2]=A('<h1 id="功耗墙与-dennard-缩放" tabindex="-1">功耗墙与 Dennard 缩放 <a class="header-anchor" href="#功耗墙与-dennard-缩放" aria-label="Permalink to &quot;功耗墙与 Dennard 缩放&quot;">​</a></h1><div class="epigraph"><p>Dennard 缩放曾让电压与尺寸一起降，功耗密度近似不变；墙之后晶体管仍变多，瓦特不再跟面积成比例让出，频率停在墙上。</p><footer>—— 据 Dennard et al., Design of Ion-Implanted MOSFETs with Very Small Physical Dimensions, IEEE JSSC 1974；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/clock-gating-dvfs">上一课</a>给出门控与 DVFS。<a href="/cs/power-dynamic-static">动态与静态功耗</a>写了 \\(CV^2f\\)。缺口是历史约束：<strong>Dennard 缩放</strong>为何曾允许每代升高 \\(f\\)，以及功耗墙如何逼出多核与暗硅——否则摩尔课只剩晶体管计数口号。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Dennard 等 1974：线性尺寸 \\(1/k\\)，电压 \\(1/k\\)，则电场大致不变，延迟降、功耗/器件降，\\(k^2\\) 倍密度下功耗密度近似恒定。缺口不是再推 \\(CV^2f\\)，而是：阈值电压不能按比例无限降（漏电指数上升），\\(V\\) 降不动则 \\(CV^2f\\) 在密度上升时把功耗密度顶破。频率不再每代自动涨，这就是功耗墙。</p><p><span class="marginnote">数字实例：\\(P = C V^2 f\\) 里的电压是平方项。电压从 5 V 降到 1 V，仅 \\(V^2\\) 一项就缩到原来的 1/25——这就是 Dennard 时代「晶体管更多、总功耗却不涨」的发动机。墙后 \\(V\\) 卡在 1 V 上下降不动，密度翻一倍，功率就几乎跟着翻倍，每平方毫米的瓦数直线上扬。</span></p><p>暗硅：同一时刻只能点亮部分芯片，否则无法散热。与把整片华莱士树每拍翻满相冲突——算术单元要可门控。</p><h3 id="功耗墙不是「摩尔定律死了」" tabindex="-1">功耗墙不是「摩尔定律死了」 <a class="header-anchor" href="#功耗墙不是「摩尔定律死了」" aria-label="Permalink to &quot;功耗墙不是「摩尔定律死了」&quot;">​</a></h3><p>晶体管密度仍可增（下一课经济学与工艺节点），只是<strong>性能/瓦</strong>的旧公式断了。把两句话当成同一句，会既说错 Dennard 也说错 Moore。多核、加速器、近存计算是墙之后的体系结构回答，本课只钉物理来源。</p><p><span class="marginnote">Dennard et al., <em>IEEE JSSC</em>, 1974。Esmaeilzadeh 等关于暗硅的论述在体系结构文献中广泛引用；CA:AQA 有功耗与多核转折的教材叙述。本课不发明 arXiv 号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照缩放表：理想 Dennard vs 后墙（\\(V\\) 近停滞、\\(f\\) 近停滞、\\(N\\) 仍增）。设计含义：并行度换吞吐、加速专用单元（FMA 阵列）只在使用时点亮、DVFS 在负载曲线上爬。STA 的目标频率由热设计功耗（TDP）封顶，不是由组合逻辑能跑多快单独决定。</p>',12)),(E(),l(d,null,{default:n(()=>[s(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEN%5B%22Dennard%EF%BC%9AV%20%E4%B8%8E%E5%B0%BA%E5%AF%B8%E5%90%8C%E9%99%8D%22%5D%20--%3E%20WALL%5B%22V%20%E5%81%9C%E3%80%81%E6%BC%8F%E7%94%B5%E3%80%81%E5%8A%9F%E8%80%97%E5%AF%86%E5%BA%A6%22%5D%0A%20%20WALL%20--%3E%20FREQ%5B%22%E9%A2%91%E7%8E%87%E5%A2%99%22%5D%0A%20%20FREQ%20--%3E%20PARA%5B%22%E5%B9%B6%E8%A1%8C%E4%B8%8E%E6%9A%97%E7%A1%85%22%5D%0A%20%20PARA%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%91%A9%E5%B0%94%E7%BB%8F%E6%B5%8E%E5%AD%A6%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"FPGA 同样受墙约束，LUT 翻转与静态漏电一起进 TDP。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"下一课把「能不能继续缩小」改写成成本、良率与设计费用，而不是电场。本课给体系结构的约束：CPI 再低，瓦特封顶则要降 \\(f\\) 或关单元。验证测试向量的高翻转会超过功能 TDP，需要分模式。",-1)),a[6]||(a[6]=e("p",null,"同一个「把晶体管做小一半」的动作，墙前与墙后兑现的东西完全不同：",-1)),(E(),l(d,null,{default:n(()=>[s(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%8A%8A%E7%BA%BF%E6%80%A7%E5%B0%BA%E5%AF%B8%E7%BC%A9%E5%88%B0%201%2F2%22%5D%20--%3E%20A%5B%22%E5%A2%99%E5%89%8D%EF%BC%9A%E7%90%86%E6%83%B3%20Dennard%22%5D%0A%20%20Q%20--%3E%20B%5B%22%E5%A2%99%E5%90%8E%EF%BC%9AV%20%E9%99%8D%E4%B8%8D%E5%8A%A8%22%5D%0A%20%20A%20--%3E%20A1%5B%22V%20%E9%99%8D%E8%87%B3%201%2F2%EF%BC%8Cf%20%E5%BE%97%E4%BB%A5%E6%8F%90%E5%8D%87%22%5D%0A%20%20A1%20--%3E%20A2%5B%22%E5%AF%86%E5%BA%A6%20%C3%974%EF%BC%8C%E5%8A%9F%E8%80%97%E5%AF%86%E5%BA%A6%E8%BF%91%E4%BC%BC%E4%B8%8D%E5%8F%98%22%5D%0A%20%20B%20--%3E%20B1%5B%22V%20%E5%81%9C%E6%BB%9E%EF%BC%8Cf%20%E5%81%9C%E6%BB%9E%EF%BC%8C%E6%BC%8F%E7%94%B5%E6%8A%AC%E5%A4%B4%22%5D%0A%20%20B1%20--%3E%20B2%5B%22%E5%AF%86%E5%BA%A6%20%C3%974%EF%BC%8C%E5%8A%9F%E8%80%97%E5%AF%86%E5%BA%A6%E8%B7%9F%E7%9D%80%E6%B6%A8%EF%BC%9A%E6%95%A3%E7%83%AD%E9%A1%B6%E4%B8%8D%E4%BD%8F%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=A('<p><span class="marginnote">直觉类比：墙后的芯片像一座只够一半路灯通电的城市——灯（晶体管）越装越多，电厂（散热能力）却不再扩容，于是同一时刻只能点亮一部分街区，这就是「暗硅」。工程师的对策：给灯装开关（门控）、按需调亮（DVFS），或换更省电的灯（专用加速单元）。</span></p><p><span class="marginnote">常见误区：初学者容易把「功耗墙」听成「摩尔定律死了」。墙断掉的是「性能/瓦随缩放自动改善」这一条；晶体管密度仍在涨，那归下一课的经济学与工艺节点管。正因为墙只封了频率和功率，业界的出路才是多核与专用单元，而不是停止做小。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不推导短沟道效应全套方程，不预测某年之后的节点名。不把大模型训练集群的 MW 当成 Dennard 的反例展开。不进入光刻能否成像更小栅——那是光刻栏。</p><p>后课默认：Dennard 缩放已破，功耗密度限制同时点亮的逻辑；频率不是免费礼物。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Dennard：尺寸与电压同降，功耗密度近似不变。</li><li>墙：\\(V\\) 与漏电，频率停，暗硅出现。</li><li>门控/DVFS/专用单元是墙后的工程回答。</li><li>出处：Dennard et al., <em>IEEE JSSC</em>, 1974；Hennessy and Patterson, CA:AQA。</li></ul>',7))])}const u=o(p,[["render",D]]);export{c as __pageData,u as default};
